(function(global){
  class MiniChart {
    static defaults = { font: {}, color: '#6B7077' };
    constructor(canvas, config){
      this.canvas = canvas;
      this.ctx = canvas && canvas.getContext ? canvas.getContext('2d') : null;
      this.config = config || {};
      this.data = this.config.data || { labels: [], datasets: [] };
      this.options = this.config.options || {};
      this.type = this.config.type || 'line';
      this.update();
    }
    update(){
      if (!this.ctx || !this.canvas) return;
      const rect = this.canvas.getBoundingClientRect();
      const dpr = global.devicePixelRatio || 1;
      const width = Math.max(1, Math.floor((rect.width || this.canvas.clientWidth || 300) * dpr));
      const height = Math.max(1, Math.floor((rect.height || this.canvas.clientHeight || 180) * dpr));
      if (this.canvas.width !== width) this.canvas.width = width;
      if (this.canvas.height !== height) this.canvas.height = height;
      const ctx = this.ctx;
      ctx.clearRect(0,0,width,height);
      ctx.save();
      ctx.scale(dpr,dpr);
      const w = width / dpr;
      const h = height / dpr;
      ctx.font = '12px Inter, sans-serif';
      ctx.strokeStyle = '#E7E3DA';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(32, 12); ctx.lineTo(32, h - 28); ctx.lineTo(w - 12, h - 28); ctx.stroke();
      if (this.type === 'doughnut') this.drawDoughnut(w,h); else this.drawLines(w,h);
      ctx.restore();
    }
    drawLines(w,h){
      const labels = this.data.labels || [];
      const datasets = this.data.datasets || [];
      const values = datasets.flatMap(ds => (ds.data || []).map(Number).filter(Number.isFinite));
      const max = Math.max(1, ...values);
      const min = Math.min(0, ...values);
      const range = max - min || 1;
      const left = 36, top = 16, right = w - 16, bottom = h - 32;
      datasets.forEach((ds, di) => {
        const data = ds.data || [];
        const color = ds.borderColor || ds.backgroundColor || ['#3C5A78','#10B981','#F59E0B','#EF4444'][di % 4];
        this.ctx.strokeStyle = color;
        this.ctx.lineWidth = 2;
        this.ctx.beginPath();
        data.forEach((raw, i) => {
          const x = left + ((right - left) * (labels.length <= 1 ? 0 : i / Math.max(1, labels.length - 1)));
          const y = bottom - ((Number(raw || 0) - min) / range) * (bottom - top);
          if (i === 0) this.ctx.moveTo(x,y); else this.ctx.lineTo(x,y);
        });
        this.ctx.stroke();
      });
    }
    drawDoughnut(w,h){
      const ds = (this.data.datasets || [])[0] || { data: [] };
      const data = (ds.data || []).map(Number);
      const total = data.reduce((a,b)=>a+(Number.isFinite(b)?b:0),0) || 1;
      const colors = ds.backgroundColor || ['#10B981','#3C5A78','#EF4444','#F59E0B'];
      const cx = w/2, cy = h/2, r = Math.max(20, Math.min(w,h)/3);
      let start = -Math.PI/2;
      data.forEach((value, i) => {
        const angle = (value/total)*Math.PI*2;
        this.ctx.beginPath();
        this.ctx.moveTo(cx,cy);
        this.ctx.fillStyle = colors[i % colors.length];
        this.ctx.arc(cx,cy,r,start,start+angle);
        this.ctx.closePath();
        this.ctx.fill();
        start += angle;
      });
      this.ctx.globalCompositeOperation = 'destination-out';
      this.ctx.beginPath(); this.ctx.arc(cx,cy,r*0.6,0,Math.PI*2); this.ctx.fill();
      this.ctx.globalCompositeOperation = 'source-over';
    }
    destroy(){ if (this.ctx) this.ctx.clearRect(0,0,this.canvas.width,this.canvas.height); }
  }
  global.Chart = global.Chart || MiniChart;
})(window);
